def simulate_3x3(rounds):
    # 3x3 grid, indexed 0 to 2. Center is (1, 1). Corners are (0,0), (0,2), (2,0), (2,2).
    H = [[0] * 3 for _ in range(3)]
    corners = [(0, 0), (0, 2), (2, 0), (2, 2)]
    center = (1, 1)

    for k in range(rounds):
        # Gardener's move (G) targeting center
        # All 9 squares are affected
        for i in range(3):
            for j in range(3):
                H[i][j] += 1

        # Lumberjack's move (L) targeting 4 corners
        for r, c in corners:
            if H[r][c] > 0:
                H[r][c] -= 1

    return H[center[0]][center[1]]

# Simulate 5 rounds
height_after_5_rounds = simulate_3x3(5)
print(f"Height of center square after 5 rounds with L targeting corners: {height_after_5_rounds}")
